// Un élément par pièce jointe exploitable (PDF, PNG, JPEG, Excel, CSV) ; un e-mail sans document est signalé.
const ACCEPTE = ['application/pdf', 'image/png', 'image/jpeg',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'text/csv'];
const EXTENSIONS = /\.(pdf|png|jpe?g|xlsx|csv)$/i;   // un CSV arrive souvent avec un type générique
const adresse = de => (String(de || '').match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/) || [''])[0].toLowerCase();
const sortie = [];
for (const mail of $input.all()) {
  const deposant = adresse(mail.json.from);
  const sujet = mail.json.subject || '';
  const pieces = Object.values(mail.binary || {}).filter(b => ACCEPTE.includes(b.mimeType) || EXTENSIONS.test(b.fileName || ''));
  if (!pieces.length) { sortie.push({ json: { flux: 'sans_document', deposant, sujet } }); continue; }
  for (const b of pieces) {
    sortie.push({ json: { flux: 'dossier', source: 'n8n-email', deposant, sujet, nom_fichier: b.fileName || 'document' },
                  binary: { document: b } });
  }
}
return sortie;

// Le fichier du champ « Document » devient la pièce « document » attendue par l'appel à l'API.
return $input.all().map(i => ({
  json: { flux: 'dossier', source: 'n8n-formulaire', deposant: String(i.json['Adresse e-mail'] || '').trim().toLowerCase(),
          nom: i.json['Nom'] || '', commentaire: i.json['Commentaire'] || '',
          nom_fichier: i.binary?.Document?.fileName || 'document' },
  binary: { document: i.binary.Document },
}));

// Dépôt par requête HTTP (démo, scripts) : curl.exe -F "file=@doc.pdf" -F "email=nom@exemple.fr" ...
// Sans champ email, la note part au valideur (Paramètres).
return $input.all().map(i => {
  const fichiers = Object.values(i.binary || {});
  const deposant = String(i.json.body?.email || '').trim().toLowerCase();
  if (!fichiers.length) return { json: { flux: 'sans_document', deposant, sujet: 'dépôt par webhook' } };
  return { json: { flux: 'dossier', source: 'n8n-webhook', deposant, nom_fichier: fichiers[0].fileName || 'document' },
           binary: { document: fichiers[0] } };
});

// Dossier déjà analysé (réponse de /v1/case), envoyé par l'API (site web, N8N_VALIDATION_URL)
// ou par la branche « dossier » de ce workflow (dépôt par e-mail, formulaire, webhook).
const corps = $input.first().json.body || {};
return [{ json: { ...corps, flux: 'validation' } }];

// n8n lance ce déclencheur quand une exécution de CE workflow échoue (hors exécution manuelle).
const e = $input.first().json;
return [{ json: { flux: 'erreur', workflow: e.workflow?.name ?? '?', noeud: e.execution?.lastNodeExecuted ?? '?',
  message: e.execution?.error?.message ?? e.trigger?.error?.message ?? '?',
  url: e.execution?.url ?? '(pas d\'URL)', mode: e.execution?.mode ?? '?' } }];

// À ADAPTER : les SEULS réglages de tout le processus. Le jeton reste « change-moi » et l'adresse
// « votre.adresse@gmail.com » dans le fichier commité ; mettez vos valeurs dans n8n, jamais dans Git.
const parametres = {
  valideur: 'votre.adresse@gmail.com',             // reçoit les dossiers à valider et les alertes
  expediteur: 'Copilote IFRS 17 <votre.adresse@gmail.com>',  // l'adresse du compte SMTP
  api: 'http://127.0.0.1:8000',                   // 127.0.0.1 et non localhost (F-002)
  jeton: 'change-moi',                            // valeur d'API_TOKEN du .env
  validation: 'http://127.0.0.1:5678/webhook/ifrs17/validation',  // webhook de validation de CE workflow
};
const j = $input.item.json;
// sans adresse de déposant (site web, webhook sans champ email), la note part au valideur
return { json: { ...j, deposant: j.deposant || parametres.valideur, parametres }, binary: $input.item.binary };

