// Prépare l'e-mail de validation et le formulaire pré-rempli avec les données extraites.
const r = $input.first().json;
const p = r.portfolio || {};
const lic = r.kind === 'lic';   // triangle de sinistres survenus (D-083) : approbation de la note, sans formulaire de cellules
const liste = v => Array.isArray(v) ? v.join(' ; ') : (v ?? '');
const unite = { 1: 'unités', 1000: 'milliers', 1000000: 'millions' }[p.unit_multiplier] || '';
const controles = (r.controls || []).map(c => '- ' + c).join('\n') || '- aucun contrôle détaillé';
const autres = (r.groups || []).slice(1).map(g => g.portfolio);   // autres groupes du document (D-078)
const csm = lic && r.lic
  ? `passif pour sinistres survenus (LIC) provisoire : ${r.lic.lic.toFixed(2)} ${r.triangle?.currency || ''}`
  : r.csm
  ? `${r.csm.onerous ? 'composante de perte' : 'CSM initiale'} provisoire : ${(r.csm.onerous ? r.csm.initial_loss_component : r.csm.initial_csm).toFixed(2)} ${p.currency || ''} (${unite})`
  : 'CSM non calculée : aucune donnée exploitable';
const message = [
  `Dossier ${r.case_id} : un contrôle n'est pas passé, la note ne peut pas partir sans vous.`,
  r.deposant ? `Déposé par : ${r.deposant}` : 'Déposé depuis le site web.',
  '', 'Contrôles non passés :', controles, '', csm, '',
  'La note provisoire vous a été envoyée dans un e-mail séparé.',
  'Cliquez sur « Vérifier les données » : le formulaire est pré-rempli avec les données extraites.',
  'Corrigez ce qui est faux, puis choisissez Approuver (la note définitive est recalculée et envoyée) ou Rejeter.',
  'Listes : une valeur par période, séparées par des points-virgules ; la virgule sert de séparateur décimal.',
  ...(autres.length ? ['', `Le document contient ${autres.length + 1} groupes : le formulaire corrige le groupe `
    + `${p.group_id} ; les autres (${autres.map(g => g.group_id).join(', ')}) sont repris tels quels dans la note.`] : []),
].join('\n');
const champ = (fieldLabel, defaultValue, extra = {}) =>
  ({ fieldLabel, fieldType: 'text', defaultValue: String(defaultValue ?? ''), requiredField: true, ...extra });
const formulaireLic = [
  { fieldLabel: 'Décision', fieldType: 'dropdown', defaultValue: 'Approuver',
    fieldOptions: { values: [{ option: 'Approuver' }, { option: 'Rejeter' }] }, requiredField: true },
  { fieldLabel: 'Commentaire', fieldType: 'textarea', requiredField: false },
];
const formulaire = [
  { fieldLabel: 'Décision', fieldType: 'dropdown', defaultValue: 'Approuver',
    fieldOptions: { values: [{ option: 'Approuver' }, { option: 'Rejeter' }] }, requiredField: true },
  champ('Groupe de contrats', p.group_id),
  champ('Devise', p.currency || 'EUR'),
  champ('Unité (1, 1000 ou 1000000)', p.unit_multiplier ?? 1),
  champ('Primes par période', liste(p.premiums), { fieldType: 'textarea' }),
  champ('Sorties par période', liste(p.outflows), { fieldType: 'textarea' }),
  champ('Recouvrements par période (facultatif)', p.recoveries ? liste(p.recoveries) : '',
        { fieldType: 'textarea', requiredField: false }),
  champ("Frais d'acquisition par période (facultatif)", p.acquisition_costs ? liste(p.acquisition_costs) : '',
        { fieldType: 'textarea', requiredField: false }),
  champ('Durée de couverture en mois (facultatif)', p.coverage_months ?? '', { requiredField: false }),
  champ('Branche (facultatif)', p.line_of_business ?? '', { requiredField: false }),
  champ('Unités de couverture par période', liste(p.coverage_units), { fieldType: 'textarea' }),
  champ("Taux d'actualisation", liste(p.discount_rates ?? 0)),
  champ('Ajustement pour risque (0 à 1)', p.risk_adjustment_pct ?? 0),
  { fieldLabel: 'Commentaire', fieldType: 'textarea', requiredField: false },
];
return [{ json: {
  case_id: r.case_id, statut: r.status,
  sujet: `IFRS 17 · dossier ${r.case_id} à valider (${(r.controls || []).length} contrôle(s) non passé(s))`,
  message: lic ? message.replace('le formulaire est pré-rempli avec les données extraites', 'dossier de sinistres survenus : '
    + 'comparez le triangle de la note au document ; une cellule fausse se corrige sur le site (ou rejetez)') : message,
  formulaire: lic ? formulaireLic : formulaire, portfolio_extrait: p, autres_groupes: autres,
  kind: r.kind || 'lrc', triangle_extrait: r.triangle || null,
  note_provisoire_html: r.note_html || '<p>Aucune note provisoire : le document est illisible.</p>',
} }];

// Lit la réponse du formulaire et reconstruit les données du portefeuille (PortfolioData).
const f = $input.first().json.data;
const prep = $('Préparer la validation').first().json;
const nombre = (s, nom) => {
  const t = String(s ?? '').replace(/\s/g, '').replace(',', '.');
  const x = Number(t);
  if (t === '' || !Number.isFinite(x)) throw new Error(`${nom} : « ${s} » n'est pas un nombre`);
  return x;
};
const liste = (s, nom) => String(s ?? '').split(';').map(t => t.trim()).filter(t => t !== '')
  .map(t => nombre(t, nom));
const decision = f['Décision'];
const commentaire = f['Commentaire'] || '';
if (decision !== 'Approuver') {
  return [{ json: { case_id: prep.case_id, decision, commentaire } }];
}
if (prep.kind === 'lic') {   // dossier LIC (D-083) : le triangle lu est approuvé tel quel
  return [{ json: { case_id: prep.case_id, decision, commentaire, triangle: prep.triangle_extrait } }];
}
const taux = liste(f["Taux d'actualisation"], "Taux d'actualisation");
const portfolio = {
  group_id: String(f['Groupe de contrats']).trim(),
  currency: String(f['Devise']).trim().toUpperCase(),
  unit_multiplier: nombre(f['Unité (1, 1000 ou 1000000)'], 'Unité'),
  premiums: liste(f['Primes par période'], 'Primes'),
  outflows: liste(f['Sorties par période'], 'Sorties'),
  coverage_units: liste(f['Unités de couverture par période'], 'Unités de couverture'),
  discount_rates: taux.length === 1 ? taux[0] : (taux.length ? taux : 0),
  risk_adjustment_pct: nombre(f['Ajustement pour risque (0 à 1)'], 'Ajustement pour risque'),
};
// recouvrements (B65 k, D-071) : facultatifs ; vide ou que des zéros = aucun
const rec = liste(f['Recouvrements par période (facultatif)'], 'Recouvrements');
if (rec.some(x => x !== 0)) portfolio.recoveries = rec;
// frais d'acquisition (B65 e, D-075), durée de couverture (PAA, D-073) et branche (RA, D-074) : facultatifs
const acq = liste(f["Frais d'acquisition par période (facultatif)"], "Frais d'acquisition");
if (acq.some(x => x !== 0)) portfolio.acquisition_costs = acq;
const duree = String(f['Durée de couverture en mois (facultatif)'] ?? '').trim();
if (duree) portfolio.coverage_months = Math.round(nombre(duree, 'Durée de couverture'));
const branche = String(f['Branche (facultatif)'] ?? '').trim();
if (branche) portfolio.line_of_business = branche;
// ajustements de service futur : repris tels quels s'ils ont toujours le bon nombre de périodes
for (const k of ['declared_cv', 'declared_confidence']) {   // D-082 : repris tels quels
  const v = (prep.portfolio_extrait || {})[k];
  if (typeof v === 'number') portfolio[k] = v;
}
const fsa = (prep.portfolio_extrait || {}).future_service_adjustments;
if (Array.isArray(fsa) && fsa.length === portfolio.premiums.length) {
  portfolio.future_service_adjustments = fsa;
}
return [{ json: { case_id: prep.case_id, decision, commentaire, portfolio, other_groups: prep.autres_groupes || [] } }];

